package com.ecopulse; import com.ecopulse.repository.*; import com.ecopulse.service.*; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import static org.junit.jupiter.api.Assertions.*; import java.util.*; class AnalyticsServiceTest { @Test void emptySummaryIsSafe(){var r=Mockito.mock(ConsumptionRepository.class);var b=Mockito.mock(BuildingRepository.class);Mockito.when(r.findByOrganizationIdAndRecordedAtBetweenOrderByRecordedAtAsc(Mockito.anyLong(),Mockito.any(),Mockito.any())).thenReturn(List.of());var s=new AnalyticsService(r,b).summary(1L,java.time.Instant.now().minusSeconds(10),java.time.Instant.now());assertEquals(0,s.records());assertEquals(0,s.sustainabilityScore());} }
